theorem coefficient_periodic (M : ℕ) (hM : 0 < M) (n : ℤ) {F : ℂ → ℂ} {y : ℝ}
    (hc : Continuous fun x : ℝ => F (point x y)) (hper : ∀ x : ℝ, F (point (x + 1) y) = F (point x y)) :
    coefficient M n F y = if (M : ℤ) ∣ n then coefficient 1 (n / M) F y else 0

